class MegaZoneError(Exception):
    def __init__(self, io_error, err_code, err_msg):
        self.io_err_msg = str(io_error)
        self.err_code = err_code
        self.err_msg = err_msg

    def __str__(self):
        reason = 'code {}. {}'.format(self.err_code, self.err_msg) if self.err_code is not None else str(self.err_msg)
        return '{}\n    caused {}'.format(reason, self.io_err_msg)


